INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Überwachung eines Netzwerks notwendig, um Leistungsprobleme zu erkennen?', 2, '[{"text": "Ja", "correct": true, "because": "Überwachung hilft, Engpässe zu identifizieren"}, {"text": "Nein", "correct": false, "because": "Überwachung ist essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Netzwerküberwachung ohne spezielle Software erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Tools sind für effektive Überwachung nötig"}, {"text": "Ja", "correct": false, "because": "Manuelle Überwachung ist ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird das Protokoll SNMP häufig für die Netzwerküberwachung verwendet?', 2, '[{"text": "Ja", "correct": true, "because": "Simple Network Management Protocol ist Standard"}, {"text": "Nein", "correct": false, "because": "SNMP ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Sicherheitsereignisse bei der Netzwerküberwachung protokolliert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Protokollierung hilft bei der Analyse"}, {"text": "Nein", "correct": false, "because": "Sicherheitsprotokolle sind wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Überwachung die Verfügbarkeit von Servern im Netzwerk prüfen?', 2, '[{"text": "Ja", "correct": true, "because": "Verfügbarkeit ist ein Überwachungsziel"}, {"text": "Nein", "correct": false, "because": "Überwachung prüft Erreichbarkeit"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird typischerweise verwendet, um Geräte im Netzwerk zu überwachen?', 2, '[{"text": "SNMP", "correct": true, "because": "Simple Network Management Protocol ist Standard"}, {"text": "HTTP", "correct": false, "because": "Für Webzugriff, nicht Überwachung"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist bekannt für die Überwachung von Netzwerkleistung und -verfügbarkeit?', 3, '[{"text": "Nagios", "correct": true, "because": "Nagios ist ein weit verbreitetes Überwachungstool"}, {"text": "Wireshark", "correct": false, "because": "Wireshark ist für Paketanalyse"}, {"text": "Notepad", "correct": false, "because": "Kein Überwachungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metrik wird oft überwacht, um die Netzwerkleistung zu bewerten?', 2, '[{"text": "Bandbreitennutzung", "correct": true, "because": "Zeigt Auslastung des Netzwerks"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant für Netzwerk"}, {"text": "Prozessorleistung", "correct": false, "because": "Client-spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein Überwachungssystem bei der Erkennung von Ausfällen?', 2, '[{"text": "Benachrichtigung", "correct": true, "because": "Alarmiert bei Problemen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht Aufgabe der Überwachung"}, {"text": "IP-Zuweisung", "correct": false, "because": "Das macht DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Zeitraum wird oft für die Überwachung von Netzwerktrends genutzt?', 2, '[{"text": "Echtzeit", "correct": true, "because": "Echtzeitdaten zeigen aktuelle Zustände"}, {"text": "Monatlich", "correct": false, "because": "Zu selten für Trends"}, {"text": "Einmalig", "correct": false, "because": "Keine kontinuierliche Überwachung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der Netzwerküberwachung typischerweise überprüft?', 4, '[{"text": "Bandbreitennutzung", "correct": true, "because": "Zeigt Auslastung"}, {"text": "Latenz", "correct": true, "because": "Beeinflusst Reaktionszeit"}, {"text": "Geräteverfügbarkeit", "correct": true, "because": "Prüft Erreichbarkeit"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Nicht netzwerkrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle können für die Netzwerküberwachung genutzt werden?', 3, '[{"text": "SNMP", "correct": true, "because": "Standard für Geräteüberwachung"}, {"text": "ICMP", "correct": true, "because": "Für Ping und Erreichbarkeit"}, {"text": "NetFlow", "correct": true, "because": "Für Verkehrsanalyse"}, {"text": "HTTP", "correct": false, "because": "Für Web, nicht Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools sind für die Netzwerküberwachung geeignet?', 4, '[{"text": "Nagios", "correct": true, "because": "Überwacht Verfügbarkeit"}, {"text": "Zabbix", "correct": true, "because": "Umfassende Überwachung"}, {"text": "SolarWinds", "correct": true, "because": "Leistungsüberwachung"}, {"text": "Notepad", "correct": false, "because": "Kein Überwachungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Netzwerküberwachung?', 3, '[{"text": "Früherkennung von Problemen", "correct": true, "because": "Verhindert Ausfälle"}, {"text": "Leistungsoptimierung", "correct": true, "because": "Identifiziert Engpässe"}, {"text": "Hohe Anfangskosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Sicherheitsüberprüfung", "correct": true, "because": "Erkennt Anomalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ereignisse sollten bei der Überwachung protokolliert werden?', 3, '[{"text": "Geräteausfälle", "correct": true, "because": "Wichtig für Analyse"}, {"text": "Bandbreitenspitzen", "correct": true, "because": "Zeigt Leistungsprobleme"}, {"text": "Sicherheitsverletzungen", "correct": true, "because": "Erkennt Angriffe"}, {"text": "Benutzeranmeldungen", "correct": false, "because": "Client-spezifisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) SNMP wird für die Netzwerküberwachung genutzt. b) Überwachung ist nur für große Netzwerke nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SNMP ja, Überwachung auch für kleine Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Netzwerküberwachung erkennt Leistungsprobleme. b) ICMP ist irrelevant für die Überwachung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Leistung ja, ICMP für Ping"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Nagios ist ein Überwachungstool. b) Überwachung benötigt keine Protokollierung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nagios ja, Protokollierung wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Überwachung prüft die Geräteverfügbarkeit. b) Latenz ist eine wichtige Metrik.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Verfügbarkeit und Latenz sind zentral"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Netzwerküberwachung hilft bei der Sicherheitsanalyse. b) Tools wie Zabbix sind für die Überwachung ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sicherheit ja, Zabbix geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

